arguments.command:
python -c "
import parse

# Try digit-based field numbering
try:
    print('Test 1:', parse.parse('{0:d}', '42'))
except Exception as e:
    print('Test 1 error:', e)

try:
    print('Test 2:', parse.parse('{0:d} {1:d}', '42 100'))
except Exception as e:
    print('Test 2 error:', e)

try:
    print('Test 3:', parse.parse('{name:d}', '42'))
except Exception as e:
    print('Test 3 error:', e)
"
